class Solution {
    public int maxTwoEvents(int[][] events){
        Arrays.sort(events,Comparator.comparingInt(a->a[0]));
        PriorityQueue<int[]> heap=new PriorityQueue<>(Comparator.comparingInt(a->a[0]));
        int bestEnded=0,answer=0;
        for(int[] event:events){
            while(!heap.isEmpty()&&heap.peek()[0]<event[0])bestEnded=Math.max(bestEnded,heap.poll()[1]);
            answer=Math.max(answer,bestEnded+event[2]);
            heap.offer(new int[]{
                event[1],event[2]
            });
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxTwoEvents(events:Array<IntArray>):Int{
        events.sortBy{
            it[0]
        };
        val heap=java.util.PriorityQueue<IntArray>(compareBy{
            it[0]
        });
        var bestEnded=0;
        var answer=0;
        for(event in events){
            while(heap.isNotEmpty()&&heap.peek()[0]<event[0])bestEnded=maxOf(bestEnded,heap.remove()[1]);
            answer=maxOf(answer,bestEnded+event[2]);
            heap.add(intArrayOf(event[1],event[2]))
        };
        return answer
    }
}

